/* styles.css - Responsive landing page for Coffee Shop */

/* Reset and base styles */
* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html, body {
  height: 100%;
  font-family: 'Helvetica Neue', Arial, sans-serif;
  color: #333;
  background-color: #fdfdfd;
}

/* Layout container */
.container {
  display: flex;
  flex-direction: column;
  min-height: 100vh;
}

/* Header */
header {
  background: url('hero.jpg') center/cover no-repeat;
  height: 60vh;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  color: #fff;
}

header h1 {
  font-size: 3rem;
  text-shadow: 2px 2px 4px rgba(0,0,0,0.6);
}

/* Navigation */
nav {
  background-color: rgba(0,0,0,0.7);
  position: sticky;
  top: 0;
  width: 100%;
  z-index: 10;
}

nav ul {
  display: flex;
  justify-content: center;
  list-style: none;
}

nav li {
  margin: 0 1rem;
}

nav a {
  color: #fff;
  text-decoration: none;
  font-weight: 600;
  padding: 1rem 0;
  display: block;
}

/* Main content sections */
section {
  padding: 4rem 2rem;
  text-align: center;
}

section h2 {
  font-size: 2.5rem;
  margin-bottom: 1rem;
  color: #6b4f4f;
}

section p {
  max-width: 800px;
  margin: 0 auto 2rem;
  line-height: 1.6;
}

/* Features grid */
.features {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
  gap: 2rem;
  margin-top: 2rem;
}

.feature-card {
  background: #fff;
  border-radius: 8px;
  box-shadow: 0 2px 8px rgba(0,0,0,0.1);
  padding: 2rem;
  transition: transform 0.3s ease;
}

.feature-card:hover {
  transform: translateY(-5px);
}

.feature-card img {
  width: 80px;
  margin-bottom: 1rem;
}

/* Call to Action */
.cta {
  background-color: #6b4f4f;
  color: #fff;
  padding: 3rem 2rem;
}

.cta button {
  background-color: #fff;
  color: #6b4f4f;
  border: none;
  padding: 0.75rem 1.5rem;
  font-size: 1rem;
  border-radius: 4px;
  cursor: pointer;
  transition: background-color 0.3s ease;
}

.cta button:hover {
  background-color: #f0e0e0;
}

/* Footer */
footer {
  background-color: #333;
  color: #ccc;
  text-align: center;
  padding: 2rem 1rem;
}

footer a {
  color: #fff;
  text-decoration: none;
  margin: 0 0.5rem;
}

/* Responsive adjustments */
@media (max-width: 768px) {
  header {
    height: 40vh;
  }
  header h1 {
    font-size: 2rem;
  }
  nav ul {
    flex-direction: column;
  }
  nav li {
    margin: 0.5rem 0;
  }
}

@media (max-width: 480px) {
  header h1 {
    font-size: 1.5rem;
  }
  section h2 {
    font-size: 2rem;
  }
  .cta button {
    width: 100%;
    padding: 1rem;
  }
}

