/* styles.css - Responsive landing page for fictional coffee shop */

/* Reset and base styles */
* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: 'Helvetica Neue', Arial, sans-serif;
  line-height: 1.6;
  color: #333;
  background-color: #fdfdfd;
}

/* Container */
.container {
  width: 90%;
  max-width: 1200px;
  margin: 0 auto;
  padding: 20px;
}

/* Header */
header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 20px 0;
}

header .logo {
  font-size: 1.8rem;
  font-weight: bold;
  color: #6f4e37; /* coffee brown */
}

nav ul {
  list-style: none;
  display: flex;
  gap: 20px;
}

nav a {
  text-decoration: none;
  color: #6f4e37;
  font-weight: 500;
}

/* Hero Section */
.hero {
  background: url('hero.jpg') center/cover no-repeat;
  color: #fff;
  text-align: center;
  padding: 120px 20px;
}

.hero h1 {
  font-size: 3rem;
  margin-bottom: 20px;
}

.hero p {
  font-size: 1.2rem;
  margin-bottom: 30px;
}

.hero .cta {
  background-color: #c49e6c;
  color: #fff;
  padding: 12px 30px;
  border: none;
  border-radius: 4px;
  cursor: pointer;
  font-size: 1rem;
}

/* About Section */
.about {
  display: flex;
  flex-wrap: wrap;
  gap: 40px;
  align-items: center;
  padding: 60px 0;
