{"input":{"operation":"create","path":"script.js","content":"// script.js
// JavaScript for the coffee shop landing page
// Handles navigation menu toggle, smooth scrolling, and a simple coffee carousel.

document.addEventListener('DOMContentLoaded', function () {
  // Mobile navigation toggle
  const menuButton = document.getElementById('menu-toggle');
  const navMenu = document.getElementById('nav-menu');
  if (menuButton && navMenu) {
    menuButton.addEventListener('click', function () {
      navMenu.classList.toggle('open');
    });
  }

  // Smooth scrolling for anchor links
  const smoothLinks = document.querySelectorAll('a[href^="#"]');
  smoothLinks.forEach(function (link) {
    link.addEventListener('click', function (e) {
      const targetId = this.getAttribute('href').substring(1);
      const targetEl = document.getElementById(targetId);
      if (targetEl) {
        e.preventDefault();
        targetEl.scrollIntoView({ behavior: 'smooth' });
        // Close mobile menu after click
        if (navMenu && navMenu.classList.contains('open')) {
          navMenu.classList.remove('open');
        }
      }
    });
  });

  // Simple image carousel for featured coffees
  const carousel = document.getElementById('coffee-carousel');
  if (carousel) {
    const slides = carousel.querySelectorAll('.slide');
    let current = 0;
    const showSlide = (index) => {
      slides.forEach((slide, i) => {
        slide.style.display = i === index ? 'block' : 'none';
      });
    };
    const nextSlide = () => {
      current = (current + 1) % slides.length;
      showSlide(current);
    };
    // Initialize first slide
    showSlide(current);
    // Auto-rotate every 5 seconds
    setInterval(nextSlide, 5000);
  }
});
